class Novel extends DataClass implements Insertable<Novel> {
  final String id;
  final String title;
  final String authorName;
  final String description;

  /// 封面图片资产
  final String? coverAssetId;
  final String status;
  final String type;
  final String contentKind;
  final String? sourceNovelId;
  final String? contentDatabasePath;
  final int wordCount;

  /// 快速开书草稿标记：true = 尚未「加入书架」，书库不显示。
  /// 仅由显式动作清除（编辑器「加入书架」按钮 / Run novel add-to-library），不自动清。
  final bool draft;
  final String category;
  final List<String> tags;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime deletedAt;
  const Novel({
    required this.id,
    required this.title,
    required this.authorName,
    required this.description,
    this.coverAssetId,
    required this.status,
    required this.type,
    required this.contentKind,
    this.sourceNovelId,
    this.contentDatabasePath,
    required this.wordCount,
    required this.draft,
    required this.category,
    required this.tags,
    required this.createdAt,
    required this.updatedAt,
    required this.deletedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['title'] = Variable<String>(title);
    map['author_name'] = Variable<String>(authorName);
    map['description'] = Variable<String>(description);
    if (!nullToAbsent || coverAssetId != null) {
      map['cover_asset_id'] = Variable<String>(coverAssetId);
    }
    map['status'] = Variable<String>(status);
    map['type'] = Variable<String>(type);
    map['content_kind'] = Variable<String>(contentKind);
    if (!nullToAbsent || sourceNovelId != null) {
      map['source_novel_id'] = Variable<String>(sourceNovelId);
    }
    if (!nullToAbsent || contentDatabasePath != null) {
      map['content_database_path'] = Variable<String>(contentDatabasePath);
    }
    map['word_count'] = Variable<int>(wordCount);
