    map['slug'] = Variable<String>(slug);
    map['name'] = Variable<String>(name);
    map['description'] = Variable<String>(description);
    map['prompt'] = Variable<String>(prompt);
    map['category'] = Variable<String>(category);
    map['mode'] = Variable<String>(mode);
    map['enabled'] = Variable<bool>(enabled);
    map['use_custom_prompt'] = Variable<bool>(useCustomPrompt);
    map['sort_order'] = Variable<int>(sortOrder);
    {
      map['allowed_tool_names'] = Variable<String>(
        $AgentsTable.$converterallowedToolNames.toSql(allowedToolNames),
      );
    }
    {
      map['ignored_skill_names'] = Variable<String>(
        $AgentsTable.$converterignoredSkillNames.toSql(ignoredSkillNames),
      );
    }
    if (!nullToAbsent || providerId != null) {
      map['provider_id'] = Variable<String>(providerId);
    }
    if (!nullToAbsent || model != null) {
      map['model'] = Variable<String>(model);
    }
    if (!nullToAbsent || reasoningEffort != null) {
      map['reasoning_effort'] = Variable<String>(reasoningEffort);
    }
    if (!nullToAbsent || avatarPath != null) {
      map['avatar_path'] = Variable<String>(avatarPath);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['deleted_at'] = Variable<DateTime>(deletedAt);
    return map;
  }

