    map['type'] = Variable<String>(type);
    map['enabled'] = Variable<bool>(enabled);
    map['api_key'] = Variable<String>(apiKey);
    map['base_url'] = Variable<String>(baseUrl);
    {
      map['models'] = Variable<String>(
        $AiProvidersTable.$convertermodels.toSql(models),
      );
    }
    {
      map['image_models'] = Variable<String>(
        $AiProvidersTable.$converterimageModels.toSql(imageModels),
      );
    }
    {
      map['audio_models'] = Variable<String>(
        $AiProvidersTable.$converteraudioModels.toSql(audioModels),
      );
    }
    {
      map['video_models'] = Variable<String>(
        $AiProvidersTable.$convertervideoModels.toSql(videoModels),
      );
    }
    {
      map['embedding_models'] = Variable<String>(
        $AiProvidersTable.$converterembeddingModels.toSql(embeddingModels),
      );
    }
    map['temperature'] = Variable<double>(temperature);
    map['max_turns'] = Variable<int>(maxTurns);
    if (!nullToAbsent || reasoningEffort != null) {
      map['reasoning_effort'] = Variable<String>(reasoningEffort);
    }
    map['proxy_url'] = Variable<String>(proxyUrl);
    map['proxy_username'] = Variable<String>(proxyUsername);
    map['proxy_password'] = Variable<String>(proxyPassword);
    if (!nullToAbsent || accessKeyId != null) {
      map['access_key_id'] = Variable<String>(accessKeyId);
    }
    if (!nullToAbsent || secretAccessKey != null) {
      map['secret_access_key'] = Variable<String>(secretAccessKey);
    }
    if (!nullToAbsent || assetProjectName != null) {
      map['asset_project_name'] = Variable<String>(assetProjectName);
    }
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['deleted_at'] = Variable<DateTime>(deletedAt);
    return map;
  }

