class AiUsageRecord extends DataClass implements Insertable<AiUsageRecord> {
  final String id;
  final String providerId;
  final String model;
  final String? sessionId;
  final String? novelId;

  /// 统计来源，取值见 `UsageSources`；写入值必须与枚举一致，新增枚举值需先与用户确认。
  final String source;

  /// 单次用户发起运行的标识。用于把同一子会话中的多次 SpawnAgent 调用拆开。
  final String? runId;

  /// 运行的用户可读摘要。当前由 SpawnAgent task 提供。
  final String? runLabel;
  final int inputTokens;
  final int outputTokens;
  final int cacheReadTokens;
  final int cacheWriteTokens;
  final int reasoningTokens;
  final DateTime createdAt;
  const AiUsageRecord({
    required this.id,
    required this.providerId,
    required this.model,
    this.sessionId,
    this.novelId,
    required this.source,
    this.runId,
    this.runLabel,
    required this.inputTokens,
    required this.outputTokens,
    required this.cacheReadTokens,
    required this.cacheWriteTokens,
    required this.reasoningTokens,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['provider_id'] = Variable<String>(providerId);
    map['model'] = Variable<String>(model);
    if (!nullToAbsent || sessionId != null) {
      map['session_id'] = Variable<String>(sessionId);
    }
    if (!nullToAbsent || novelId != null) {
      map['novel_id'] = Variable<String>(novelId);
    }
    map['source'] = Variable<String>(source);
    if (!nullToAbsent || runId != null) {
      map['run_id'] = Variable<String>(runId);
    }
    if (!nullToAbsent || runLabel != null) {
      map['run_label'] = Variable<String>(runLabel);
    }
    map['input_tokens'] = Variable<int>(inputTokens);
    map['output_tokens'] = Variable<int>(outputTokens);
    map['cache_read_tokens'] = Variable<int>(cacheReadTokens);
    map['cache_write_tokens'] = Variable<int>(cacheWriteTokens);
    map['reasoning_tokens'] = Variable<int>(reasoningTokens);
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  AiUsagesCompanion toCompanion(bool nullToAbsent) {
    return AiUsagesCompanion(
      id: Value(id),
      providerId: Value(providerId),
      model: Value(model),
      sessionId: sessionId == null && nullToAbsent
          ? const Value.absent()
          : Value(sessionId),
      novelId: novelId == null && nullToAbsent
          ? const Value.absent()
          : Value(novelId),
      source: Value(source),
      runId: runId == null && nullToAbsent
          ? const Value.absent()
          : Value(runId),
      runLabel: runLabel == null && nullToAbsent
          ? const Value.absent()
          : Value(runLabel),
      inputTokens: Value(inputTokens),
      outputTokens: Value(outputTokens),
      cacheReadTokens: Value(cacheReadTokens),
      cacheWriteTokens: Value(cacheWriteTokens),
      reasoningTokens: Value(reasoningTokens),
      createdAt: Value(createdAt),
    );
  }

